import numpy as np, torch, model, os
print(os.getcwd(), os.listdir('.'))
torch.manual_seed(0)
net = model.load()
N=4096; rng=np.random.default_rng(1)
xi=torch.tensor(rng.standard_normal((N,2)),dtype=torch.float32); c=torch.tensor(rng.random(N),dtype=torch.float32)
def ang(a): return np.degrees(np.arctan2(a[:,1],a[:,0]))
def lab(a,cc):
    d=(ang(a)-(137+60*cc)+180)%360-180; return np.abs(d)<22
def typ(a,cc):
    d=(ang(a)-(137+60*cc))%45; d=np.minimum(d,45-d); return d<15
J=torch.tensor([[0.,-1.],[1.,0.]])
@torch.no_grad()
def run(det=None,k0=0,k1=0,g=0.,thr=0.):
    x=xi.clone(); H=[]
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2",),count=False)
        h=a["blocks.2"]; H.append(h.numpy())
        if det is not None and k0<=k<k1:
            m=(h@det[0]+det[1])>thr
            v=v+m[:,None].float()*g*(x@J.T)
        x=x-v/20
    return x.numpy(),np.stack(H)
a0,H=run(); cn=c.numpy(); y=lab(a0,cn)
def fit(k0,k1):
    X=torch.tensor(H[k0:k1].reshape(-1,128)); Y=torch.tensor(np.tile(y,k1-k0),dtype=torch.float32)
    mu=X.mean(0); sd=X.std(0)+1e-6; Z=(X-mu)/sd
    w=torch.zeros(128,requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.Adam([w,b],lr=0.05)
    for it in range(500):
        opt.zero_grad(); l=torch.nn.functional.binary_cross_entropy_with_logits(Z@w+b,Y)+1e-4*(w**2).sum(); l.backward(); opt.step()
    return (w/sd).detach(), float((b-(mu/sd*w).sum()).detach())
for (k0,k1) in [(4,10),(8,14),(10,16)]:
    w,b=fit(k0,k1)
    s=np.stack([(H[k]@w.numpy()+b)>0 for k in range(k0,k1)])
    print('win',k0,k1,'b',round(b,4),'recall any',s.any(0)[y].mean().round(3),'ff any',s.any(0)[~y].mean().round(3))
    np.save(f'detw_{k0}_{k1}.npy',w.numpy().astype(np.float32))
    for g in [-8,-4,4,8]:
