import numpy as np, torch, model
net=model.load(); neg=model.negatives(); M=[5,6,10,11,13]
N=4096; rng=np.random.default_rng(2)
xi=torch.tensor(rng.standard_normal((N,2)),dtype=torch.float32); c=torch.tensor(rng.random(N),dtype=torch.float32)
def dec(push=None):
    x=xi.clone(); S=[x.clone()]
    for k in range(20):
        t=torch.full((N,),1-k/20); v,_=net.velocity(x,t,c,(),count=False)
        if push is not None: v=v+push(x,k,t)
        x=x-v/20; S.append(x.clone())
    return x.numpy(),torch.stack(S).numpy()
def bad(a):
    u=np.zeros(len(a),bool)
    for i in M: u|=np.asarray(model.in_basin(i,a)).astype(bool)
    return u
a0,S0=dec(); b0=bad(a0); print('base bad',b0.mean())
# where are bad trajectories at each step: angle and radius of x_k
for k in [8,10,12,14,16]:
    x=S0[k]; ang=np.degrees(np.arctan2(x[:,1],x[:,0])); r=np.linalg.norm(x,axis=1)
    print(k,'bad ang',np.percentile(ang[b0],[2,50,98]).round(0),'r',np.percentile(r[b0],[2,50]).round(2))
    # best separating halfspace along direction theta
    for th in [95,105,115]:
